from produire import produire,paras,table,steps
parts=[
('L’abcès dentoalvéolaire est une collection purulente liée à une infection dentaire. Les {distinctions de siège} permettent de rechercher la dent et le foyer responsables d’une otalgie projetée.',paras('Une collection périapicale se situe près de l’extrémité d’une racine ; une infection parodontale siège dans les tissus de soutien. La douleur peut irradier vers l’oreille alors que son examen est normal.')),
('Caries, atteinte pulpaire et maladie parodontale sont des contextes importants. Les {facteurs de retard} peuvent favoriser une extension.',paras('Un épisode douloureux peut fluctuer ou diminuer après drainage spontané sans que le foyer soit éliminé. L’absence de douleur intense n’exclut donc pas une infection nécessitant un soin dentaire.')),
('La progression bactérienne peut produire une collection puis diffuser aux tissus voisins. Les {voies de propagation} expliquent le risque cervical et respiratoire.',paras('Le drainage local et le traitement de la dent retirent la source infectieuse. Des antibiotiques seuls peuvent réduire transitoirement les symptômes sans contrôler le foyer.')),
('Rechercher d’abord extension et menace des voies aériennes. Les {signes d’alarme} imposent une prise en charge hospitalière.',paras('Gonflement du plancher ou du cou, langue soulevée, dysphagie, dyspnée, trismus important, altération générale ou sepsis nécessitent une évaluation urgente. Le terrain immunodéprimé abaisse le seuil d’orientation ; la fièvre peut manquer malgré une extension.')),
('L’entretien recherche une dent douloureuse et les signes de diffusion. Les {questions utiles} précisent évolution et traitements déjà reçus.',paras('Demander douleur à la mastication, sensibilité dentaire antérieure, gonflement, goût de pus, soins récents et épisodes similaires. Relever allergies, antibiotiques, immunodépression et capacité à boire.')),
('Examiner dents, gencives, plancher buccal et cou. Les {gestes ciblés} recherchent une dent causale et une collection.',paras('Décrire carie, fracture, tuméfaction, fistule, douleur à la percussion ou à la palpation selon compétence. Mesurer l’ouverture et rechercher asymétrie, ganglions et extension ; l’examen dentaire spécialisé complète le bilan.')),
('Le {diagnostic différentiel} distingue infection collectée et autres douleurs dentaires ou faciales. Le traitement dépend de cette distinction.',table(['Profil','Alternative'],[['Douleur dentaire sans tuméfaction collectée.','Pulpite ou autre atteinte dentaire.'],['Inflammation autour d’une dent en éruption.','Péricoronarite.'],['Douleur préauriculaire reproduite par la mâchoire.','Trouble temporo-mandibulaire.'],['Masse ou ulcère persistant.','Lésion buccale nécessitant un autre bilan.'],['Bombement pharyngé et voix étouffée.','Abcès périamygdalien ou autre infection profonde.']])) ,
('Le diagnostic associe foyer dentaire et signes infectieux locaux. Les {critères de localisation} sont précisés par le dentiste.',paras('La collection peut être fluctuante ou avoir déjà drainé. Une otoscopie normale avec lésion dentaire concordante soutient l’origine projetée, mais une otalgie persistante après traitement doit être réévaluée.')),
('L’imagerie dentaire est choisie selon le foyer suspecté. Les {examens d’extension} dépendent de la gravité.',paras('Radiographie ciblée ou autre examen dentaire pour localiser la lésion ; imagerie cervicale et bilan biologique si diffusion profonde ou signes généraux. La microbiologie est particulièrement utile dans certaines formes graves ou atypiques, sans retarder le contrôle urgent du foyer.')),
('L’{arbre de prise en charge} donne priorité au drainage et à la dent responsable. L’antibiotique répond à des indications complémentaires.',steps('Écarter menace respiratoire, sepsis et extension profonde.', 'Adresser rapidement au dentiste pour traitement du foyer et drainage approprié.', 'Envisager un antibiotique si extension, signes généraux, risque élevé ou impossibilité d’obtenir immédiatement un drainage adéquat.', 'Réévaluer réponse et accès au soin définitif ; ne pas répéter des cures seules devant une récidive.')),
('Le traitement élimine la source et permet l’évacuation du pus. Les {options dentaires} dépendent de la dent et de sa possibilité de conservation.',paras('Traitement endodontique, extraction ou incision-drainage sont choisis par le professionnel ; l’incision seule peut rester temporaire si la dent causale n’est pas traitée. Associer antalgie adaptée et soutien des apports.', 'Le SDCEP réserve l’antibiothérapie aux indications d’extension, d’atteinte générale ou de drainage immédiat non obtenu. Le choix suisse de préparation, dose et durée doit être validé selon le patient et le protocole dentaire ; les doses britanniques ne sont pas transposées. Une forme sévère relève de l’hôpital.')),
('La {prévention} passe par hygiène buccodentaire et soins réguliers. Un suivi est nécessaire même après soulagement spontané.',paras('Traiter caries et maladie parodontale, contrôler la dent après intervention et consulter en cas de nouvelle tuméfaction. Expliquer que la disparition de douleur après écoulement de pus ne signifie pas disparition de la source.')),
('Une dent infectée peut provoquer une otalgie avec oreille normale. Le contrôle du foyer est central. Les antibiotiques seuls ne remplacent pas le drainage et le soin de la dent. Gonflement du plancher et gêne respiratoire sont des urgences.','')]
quiz=[('Une infection dentaire peut-elle donner une douleur d’oreille ?','Oui : douleur projetée.'),('L’abcès doit-il toujours être très douloureux ?','Non.'),('Le drainage spontané signifie-t-il guérison définitive ?','Non : la source peut persister.'),('Quel signe menace les voies aériennes ?','Gonflement du plancher ou de la langue avec dysphagie ou dyspnée.'),('L’absence de fièvre exclut-elle une extension ?','Non.'),('Que rechercher à l’examen dentaire ?','Dent causale, carie ou fracture, tuméfaction, fistule et douleur provoquée.'),('Une pulpite est-elle identique à un abcès collecté ?','Non.'),('Quel est le principe central du traitement ?','Éliminer la source et drainer si nécessaire.'),('Un antibiotique est-il systématique dans un abcès localisé drainable ?','Non.'),('Quand peut-il être indiqué ?','Extension, signes généraux, risque élevé ou drainage adéquat immédiat non obtenu selon l’évaluation.'),('L’antibiotique seul évite-t-il toujours la diffusion ?','Non : le foyer doit être contrôlé.'),('Quelle alternative à l’extraction peut conserver certaines dents ?','Un traitement endodontique adapté.'),('Une otalgie persistant après soin dentaire doit-elle être ignorée ?','Non : revoir le diagnostic.'),('Que faire devant trismus important et tuméfaction cervicale ?','Orientation urgente pour rechercher une infection profonde.')]
produire(9,parts,quiz,(6,12))
